const state={config:null,content:null,user:null,progress:null,csrf:null,view:'dashboard',questionQueue:[],questionIndex:0,quizScore:0,selectedJob:null,selectedPerson:null,ws:null,notifications:[],community:null,timer:null,tutorial:null};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const money=v=>`GHS ${Number(v||0).toFixed(0)}`; const fmtDate=v=>{const d=new Date(v);return Number.isNaN(d.getTime())?String(v||''):d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})};
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),3200)}
function playNotifySound(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=660;o.type='sine';g.gain.value=.035;o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.12)}catch{}}
function openModal(html,wide=false){const m=$('#modal');m.classList.toggle('wide',wide);$('#modalBody').innerHTML=html;m.classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
async function api(url,opt={}){const method=(opt.method||'GET').toUpperCase();const headers={...(opt.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opt.headers||{})};if(state.csrf&&['POST','PATCH','PUT','DELETE'].includes(method))headers['X-CSRF-Token']=state.csrf;const r=await fetch(url,{...opt,method,headers,credentials:'include'});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||`Request failed (${r.status})`);return d}
function trialInfo(){const t=state.user?.trial;if(!t?.endsAt)return {active:false,expired:true,days:0,hours:0,minutes:0,seconds:0,total:0};const total=Math.max(0,new Date(t.endsAt)-Date.now());if(t.status==='active'&&total>0){const sec=Math.floor(total/1000);return {active:true,expired:false,days:Math.floor(sec/86400),hours:Math.floor(sec%86400/3600),minutes:Math.floor(sec%3600/60),seconds:sec%60,total};}return {active:false,expired:true,days:0,hours:0,minutes:0,seconds:0,total:0}}
function premium(){return Boolean(state.user?.subscription?.active)||trialInfo().active}
function membership(){return state.user?.subscription?.active?'Premium':trialInfo().active?'7-Day Trial':'Free'}
function profileRole(){return state.user?.role==='student'?'Student':'Graduate / Professional'}
function cProfile(u=state.user){if(!u)return '';return u.avatar?`<img src="${esc(u.avatar)}" alt="Profile">`:esc((u.name||'NM').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}
function goToHubFeature(view){
  if(state.user){enter(view);return;}
  state.pendingView=view;
  showSignup('student');
}
function bindGlobal(){
  $$('[data-public-view]').forEach(b=>b.onclick=()=>{const target=document.getElementById(b.dataset.publicView);if(target)target.scrollIntoView({behavior:'smooth'});$('.public-nav')?.classList.remove('open')});
  const navToggle=$('#publicNavToggle'),publicNav=$('.public-nav');
  if(navToggle&&publicNav){
    navToggle.onclick=e=>{e.stopPropagation();publicNav.classList.toggle('open')};
    if(!window.__publicNavOutsideClickBound){window.__publicNavOutsideClickBound=true;document.addEventListener('click',e=>{const n=$('.public-nav'),t=$('#publicNavToggle');if(n&&n.classList.contains('open')&&!n.contains(e.target)&&e.target!==t)n.classList.remove('open')});}
  }
  $$('[data-action="login"]').forEach(b=>b.onclick=()=>state.user?enter('dashboard'):showLogin());
  $$('[data-action="signup"]').forEach(b=>b.onclick=()=>state.user?enter('dashboard'):showSignup('student'));
  $$('[data-action="close"]').forEach(b=>b.onclick=closeModal);
  $$('[data-view-go]').forEach(b=>b.onclick=()=>enter(b.dataset.viewGo));
  $$('[data-view]').forEach(b=>b.onclick=()=>enter(b.dataset.view));
  const t=$('#sidebarToggle');if(t)t.onclick=()=>$('#sidebar').classList.toggle('open');
  const notify=$('#notifyBtn');if(notify)notify.onclick=showNotifications;
  const sub=$('[data-action="subscribe"]');if(sub)sub.onclick=showPremium;
  const signout=$('[data-action="signout"]');if(signout)signout.onclick=signOut;
  const search=$('#globalSearch');if(search)search.oninput=()=>searchAll(search.value.trim());
  const modalClose=$('.modal-close');if(modalClose)modalClose.onclick=closeModal;
  const hubToggle=$('#insideHubToggle'),hubMenu=$('#insideHubMenu');
  if(hubToggle&&hubMenu){
    hubToggle.onclick=e=>{e.stopPropagation();hubMenu.classList.toggle('open')};
    hubMenu.querySelectorAll('[data-hub-target]').forEach(b=>b.onclick=()=>{hubMenu.classList.remove('open');$('.public-nav')?.classList.remove('open');goToHubFeature(b.dataset.hubTarget)});
    if(!window.__hubMenuOutsideClickBound){window.__hubMenuOutsideClickBound=true;document.addEventListener('click',e=>{const m=$('#insideHubMenu'),t=$('#insideHubToggle');if(m&&!m.contains(e.target)&&e.target!==t)m.classList.remove('open')});}
  }
}
function renderTrialBar(){const el=$('#trialBar');if(!el)return;const t=trialInfo();if(state.user?.subscription?.active){el.className='trial-bar';el.innerHTML='<b>Premium membership active.</b><span>All Premium study, AI, community and career tools are unlocked.</span>';return}if(t.active){el.className='trial-bar';el.innerHTML=`<div><b>7-day full Premium trial</b><div class="muted">Everything is unlocked during your trial.</div></div><div class="countdown"><div class="count-box"><strong>${t.days}</strong><small>days</small></div><div class="count-box"><strong>${String(t.hours).padStart(2,'0')}</strong><small>hours</small></div><div class="count-box"><strong>${String(t.minutes).padStart(2,'0')}</strong><small>minutes</small></div><div class="count-box"><strong>${String(t.seconds).padStart(2,'0')}</strong><small>seconds</small></div></div>`;return}el.className='trial-bar ended';el.innerHTML=`<div><b>Your 7-day Premium trial has ended.</b><div>Premium tools are now locked until you subscribe.</div></div><button class="btn primary" data-action="subscribe">Subscribe · ${money(state.config?.subscriptionGhs||50)}/month</button>`;el.querySelector('[data-action="subscribe"]').onclick=showPremium}
function startTrialClock(){clearInterval(state.timer);let lastAccess=premium();state.timer=setInterval(()=>{if(!state.user)return;syncUserUI();const currentAccess=premium();if(currentAccess!==lastAccess){lastAccess=currentAccess;render();}},1000)}
function syncUserUI(){
  if(!state.user)return;$('#profileName').textContent=state.user.name?.split(' ')[0]||'Member';$('#profileRole').textContent=profileRole();$('#profileAvatar').innerHTML=cProfile();const b=$('#membershipBadge');b.textContent=membership();b.classList.toggle('active',premium());renderTrialBar();
}
