function render(){const fn={dashboard:renderDashboard,study:renderStudy,practice:renderPractice,tutorial:renderTutorial,tutor:renderTutor,nutrition:renderNutrition,jobs:renderJobs,tracker:renderTracker,abroad:renderAbroad,news:renderNews,community:renderCommunity,reels:renderReels,evaluation:renderEvaluation,stories:renderStories,enquiries:renderEnquiries,profile:renderProfile}[state.view];(fn||renderDashboard)();}
function dashboardMetrics(){const p=state.progress||{modules:{},questionsAnswered:0,correct:0,byDomain:{}};const total=state.content.syllabus.length||1;const overall=Math.round(state.content.syllabus.reduce((a,m)=>a+Number(p.modules?.[m.id]||0),0)/total);const accuracy=p.questionsAnswered?Math.round((p.correct||0)/p.questionsAnswered*100):0;return{p,overall,accuracy}}
function renderDashboard(){const {p,overall,accuracy}=dashboardMetrics();const next=state.content.syllabus.find(m=>(p.modules?.[m.id]||0)<100)||state.content.syllabus[0];const t=trialInfo();$('#workspaceContent').innerHTML=`<div class="dashboard-hero"><section class="welcome-card"><span class="eyebrow">${state.user.role==='student'?'STUDENT DASHBOARD':'PROFESSIONAL DASHBOARD'}</span><h2>Welcome back, ${esc(state.user.name.split(' ')[0])}.</h2><p>Your study, practice, career, abroad, news and community tools are organised here. Nothing important needs to be scattered across websites.</p><div class="quick-row"><button class="btn secondary" data-view-go="study">Continue learning</button><button class="btn ghost" data-view-go="practice">N&MC Practice</button><button class="btn ghost" data-view-go="tutor">Ask AI Tutor</button></div></section><section class="visual-card"><img src="/assets/hero-professionals.png" alt="Nurses and midwives learning together"></section></div><div class="kpi-grid"><div class="kpi"><span>Overall study progress</span><strong>${overall}%</strong><small>${next?.title||'All modules'} next</small></div><div class="kpi"><span>Questions answered</span><strong>${p.questionsAnswered||0}</strong><small>Original Hub practice</small></div><div class="kpi"><span>Accuracy</span><strong>${accuracy}%</strong><small>Across completed questions</small></div><div class="kpi"><span>Premium</span><strong>${membership()}</strong><small>${t.active?`${t.days} days ${t.hours}h remaining`:state.user.subscription?.active?'Recurring membership':'Upgrade required'}</small></div></div><div class="grid two"><section class="panel"><div class="panel-head"><div><span class="eyebrow">NEXT STUDY STEP</span><h3>${esc(next.title)}</h3></div><button class="btn secondary" onclick="openModule('${esc(next.id)}')">Open module</button></div><p>${esc(next.description)}</p><div class="progress-line"><i style="width:${p.modules?.[next.id]||0}%"></i></div><small class="muted">${p.modules?.[next.id]||0}% complete · ${next.lessons.length} lessons</small></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">QUICK ACCESS</span><h3>Everything at one tap</h3></div></div><div class="tool-grid"><button class="btn ghost" data-view-go="study">Study & notes</button><button class="btn ghost" data-view-go="practice">N&MC sets</button><button class="btn ghost" data-view-go="tutorial">Daily Tutorial</button><button class="btn ghost" data-view-go="nutrition">Nutrition</button><button class="btn ghost" data-view-go="jobs">Jobs</button><button class="btn ghost" data-view-go="abroad">Abroad</button><button class="btn ghost" data-view-go="community">Community</button><button class="btn ghost" data-view-go="evaluation">Document evaluation</button></div></section></div><div class="grid two"><section class="panel"><div class="panel-head"><div><span class="eyebrow">LATEST NEWS</span><h3>Read inside the Hub</h3></div><button class="btn ghost" data-view-go="news">See all</button></div>${state.content.news.slice(0,4).map(n=>`<button class="compact-row" onclick="openNews('${esc(n.id)}')"><span>${esc(n.category)}${n.locked?' · 🔒 Premium':''}</span><b>${esc(n.title)}</b><small>${esc(n.date)} · ${esc(n.source)}</small></button>`).join('')}</section><section class="panel"><div class="panel-head"><div><span class="eyebrow">COMMUNITY</span><h3>Meet other members</h3></div><button class="btn ghost" data-view-go="community">Open community</button></div><div class="chat-sneak"><div>💬 <b>Premium community</b></div><p>Friends, private messages, groups, status posts, media sharing and Hub notifications.</p><div class="fake-bubbles"><span>Anyone studying Midwifery today?</span><span>Yes — I’m on maternal health.</span><span>Let’s revise together.</span></div></div></section></div>`;afterRender()}
