window.openModule=function(id){const m=state.content.syllabus.find(x=>x.id===id);if(!m)return;state.moduleId=id;state.lessonIndex=0;openLesson()}
async function openLesson(){
  const m=state.content.syllabus.find(x=>x.id===state.moduleId);if(!m)return;
  const i=state.lessonIndex||0;const prog=state.progress?.modules?.[m.id]||0;
  const cacheKey=`${m.id}::${i}`; state.lessonNotesCache=state.lessonNotesCache||{}; const cached=state.lessonNotesCache[cacheKey];
  const lessonDone=k=>Boolean(state.progress?.lessons?.[`${m.id}::${k}`]);
  const doneCount=m.lessons.filter((_,k)=>lessonDone(k)).length;
  openModal(`<div class="module-detail"><span class="eyebrow">${esc(m.track)}</span><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p><div class="tag">Lesson ${i+1} of ${m.lessons.length}</div><span class="tag" style="background:#eef9f3;color:var(--good)">${doneCount} of ${m.lessons.length} lessons complete</span><h3>${esc(m.lessons[i])}${lessonDone(i)?' ✓':''}</h3><div class="detail-note" id="lessonNotesArea">${cached?cached:'<div class="empty">Loading your notes for this lesson…</div>'}</div><div class="lesson-list lesson-nav-list">${m.lessons.map((l,k)=>`<button class="lesson ${k===i?'active':''}" onclick="state.lessonIndex=${k};closeModal();openLesson()">${lessonDone(k)?'✓ ':''}${k+1}. ${esc(l)}</button>`).join('')}</div><div class="form-card"><label>Module progress<input id="moduleProgress" type="range" min="0" max="100" step="10" value="${prog}"></label><div class="pager"><button class="btn ghost" onclick="state.lessonIndex=Math.max(0,(state.lessonIndex||0)-1);openLesson()" ${i===0?'disabled':''}>← Previous</button><button class="btn primary" onclick="state.lessonIndex=Math.min(${m.lessons.length-1},(state.lessonIndex||0)+1);openLesson()" ${i===m.lessons.length-1?'disabled':''}>Next lesson →</button></div><button class="btn ${lessonDone(i)?'ghost':'primary'} full" onclick="markLessonComplete('${esc(m.id)}',${i})">${lessonDone(i)?'✓ Lesson marked complete':'Mark lesson complete'}</button><button class="btn secondary full" onclick="saveModuleProgress('${esc(m.id)}')">Save progress</button><button class="btn ghost full" onclick="closeModal();enter('tutor')">Ask AI about this lesson</button></div></div>`,true);
  if(cached)return;
  try{
    const d=await api('/api/ai/lesson-notes',{method:'POST',body:JSON.stringify({moduleId:m.id,lessonIndex:i})});
    const relatedHtml=(d.relatedQuestions||[]).length?`<h4>Practice this now</h4><div class="lesson-list related-question-list">${d.relatedQuestions.map(q=>`<button class="compact-row" onclick="jumpToQuestion('${esc(q.id)}')"><b>${esc(q.question)}</b><small>${esc(q.domain)}</small></button>`).join('')}</div>`:'';
    const html=`${aiModeBadge()}${d.notesHtml}${relatedHtml}`;
    state.lessonNotesCache[cacheKey]=html;
    const area=$('#lessonNotesArea'); if(area)area.innerHTML=html;
  }catch(e){
    const area=$('#lessonNotesArea'); if(area)area.innerHTML=`<div class="empty">Notes could not load: ${esc(e.message)}. <button class="btn ghost" onclick="delete state.lessonNotesCache['${esc(cacheKey)}'];openLesson()">Try again</button></div>`;
  }
}
