function renderStudy(){if(!premium())return renderLocked('Study & Notes','Your 7-day Premium trial unlocks the complete study library. Subscribe after the trial to keep access.');const p=state.progress?.modules||{};const tracks=['Nursing Core','Midwifery Core','Community & Public Health','Professional Practice','Nutrition'];$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">STUDY CATALOGUE</span><h2>Structured notes you can actually study.</h2><p>Open any module to read the lesson inside the Hub, move between lessons, save progress and ask the AI Tutor for a deeper explanation.</p></div><button class="btn primary" data-view-go="practice">Open practice</button></div><div class="resource-strip"><article><img src="/assets/study-ghana.png" alt="Nursing learners studying"><h3>Clinical learning</h3><p>Build concepts before testing yourself.</p></article><article><img src="/assets/study-australia.png" alt="Nurse and midwife learners studying internationally"><h3>Global direction</h3><p>Prepare academically and professionally.</p></article><article><img src="/assets/study-global.png" alt="Global nursing learning"><h3>AI-supported study</h3><p>Ask for another explanation whenever you need one.</p></article></div><div class="filter-pills">${tracks.map((x,i)=>`<button class="filter-pill ${i===0?'active':''}" data-track="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="grid cards-3" id="studyGrid">${state.content.syllabus.map((m,i)=>`<article class="study-card" data-track-card="${esc(m.track)}"><div class="card-top"><span class="module-no">${String(i+1).padStart(2,'0')}</span><span class="tag">${esc(m.track)}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="topic-list">${m.topics.map(t=>`<span class="topic">${esc(t)}</span>`).join('')}</div><div class="study-bottom"><span>${p[m.id]||0}%</span><div class="progress-line"><i style="width:${p[m.id]||0}%"></i></div></div><button class="btn secondary full" onclick="openModule('${esc(m.id)}')">Open module & notes</button></article>`).join('')}</div>`;$$('[data-track]').forEach(b=>b.onclick=()=>{$$('[data-track]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const t=b.dataset.track;$$('[data-track-card]').forEach(c=>c.style.display=c.dataset.trackCard===t?'':'none')});afterRender()}
function questionSets(){const qs=state.content.questions||[];const chunks=[];for(let i=0;i<qs.length;i+=10)chunks.push({id:`set-${i/10+1}`,label:`Practice Set ${i/10+1}`,range:`Questions ${i+1}-${Math.min(i+10,qs.length)}`,count:qs.slice(i,i+10).length,questions:qs.slice(i,i+10)});return chunks}
function renderPractice(){if(!premium())return renderLocked('N&MC Practice','Your 7-day Premium trial unlocks all practice sets, answers, rationales and downloads.');const p=state.progress||{};const accuracy=p.questionsAnswered?Math.round((p.correct||0)/p.questionsAnswered*100):0;$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">N&MC PREPARATION</span><h2>Open a set and start answering inside the Hub.</h2><p>These are original Hub preparation questions written in a licensing-style format. They are not presented as official N&MC or NCLEX past papers.</p></div><button class="btn secondary" onclick="downloadQuestions()">Download Hub question bank</button></div><div class="exam-banner"><div><span class="eyebrow">YOUR PERFORMANCE</span><h3>${p.questionsAnswered||0} answered · ${accuracy}% accuracy</h3><p>Domain performance updates after every completed question.</p></div><button class="btn primary" onclick="startPractice(0)">Quick 10-question practice</button></div><div class="price-card" style="margin:14px 0"><span class="eyebrow">EXAM SIMULATION</span><h3>NCLEX & N&MC Licensing Simulation</h3><p>A full timed mock exam under real exam-style pressure — a 60-minute countdown across a large mixed question set, ending with a domain-by-domain performance breakdown. Hub-authored questions covering NCLEX-style and N&MC-style licensing content; not official exam papers.</p><button class="btn primary" onclick="startSimulation()">Start 60-minute simulation</button></div><div class="practice-set-grid">${questionSets().map((s,i)=>`<article class="set-card"><span class="tag">${i<3?'CORE':'REVISION'}</span><h3>${esc(s.label)}</h3><strong>${s.count}</strong><p>${esc(s.range)} · mixed nursing, midwifery, pharmacology and public health.</p><small class="muted">Original Hub-authored practice questions — not official past examination papers.</small><button class="btn secondary full" onclick="startPractice(${i})">Open set</button></article>`).join('')}</div><div class="panel" style="margin-top:14px"><div class="panel-head"><div><span class="eyebrow">SHORT THEORY</span><h3>Write before reading the guide</h3></div></div><div class="grid two">${(state.content.questions||[]).filter(q=>q.type==='theory').slice(0,8).map(q=>`<article class="theory-card"><span class="tag">${esc(q.domain)}</span><h4>${esc(q.question)}</h4><details><summary>Reveal answer guide</summary><p>${esc(q.theoryGuide||'Review the related Study module.')}</p></details></article>`).join('')}</div></div>`;afterRender()}
window.startPractice=function(setIndex){if(!premium())return showPremium();const set=questionSets()[setIndex]||questionSets()[0];state.questionQueue=[...set.questions];state.questionIndex=0;state.quizScore=0;state.simMode=false;state.questionAnswers={};showQuizQuestion()}
function shuffleArray(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function formatSimTime(s){s=Math.max(0,s);const m=Math.floor(s/60),ss=s%60;return `${String(m).padStart(2,'0')}:${String(ss).padStart(2,'0')}`}
window.startSimulation=function(){
  if(!premium())return showPremium();
  const all=(state.content.questions||[]).filter(q=>q.type!=='theory');
  state.questionQueue=shuffleArray(all).slice(0,Math.min(60,all.length));
  state.questionIndex=0;state.quizScore=0;state.simMode=true;state.simSeconds=60*60;state.questionAnswers={};
  clearInterval(state.simTimer);
  state.simTimer=setInterval(()=>{
    state.simSeconds--;
    const el=$('#simTimer');if(el)el.textContent=formatSimTime(state.simSeconds);
    if(state.simSeconds<=0){clearInterval(state.simTimer);toast('Time is up — simulation submitted.');showQuizResult();}
  },1000);
  showQuizQuestion();
}
function showQuizQuestion(){
  const q=state.questionQueue[state.questionIndex];if(!q){return showQuizResult()}
  const timerHtml=state.simMode?`<span class="tag" id="simTimer" style="background:#fff2c6;color:#7a5c00">${formatSimTime(state.simSeconds)}</span>`:'';
  const prevBtn=`<button class="btn ghost" onclick="state.questionIndex=Math.max(0,state.questionIndex-1);showQuizQuestion()" ${state.questionIndex===0?'disabled':''}>← Previous</button>`;
  const answered=(state.questionAnswers||{})[state.questionIndex];
  if(answered){
    const isLast=state.questionIndex+1>=state.questionQueue.length;
    openModal(`<div class="quiz-area"><span class="eyebrow">${esc(q.domain)} · ${esc(q.difficulty||'Practice')}</span>${timerHtml}<h2>Question ${state.questionIndex+1} of ${state.questionQueue.length}</h2><div class="quiz-question"><h3>${esc(q.question)}</h3><p><b>${answered.correct?'CORRECT':'REVIEW'} — your answer:</b> ${esc((q.options||[])[answered.answer]||'—')}</p><p><b>Correct answer:</b> ${esc((q.options||[])[answered.correctAnswer]??'See guide')}</p><div class="detail-note"><h4>Why</h4><p>${esc(answered.explanation||'Review the related module notes.')}</p></div><div class="pager">${prevBtn}<button class="btn primary" onclick="state.questionIndex++;showQuizQuestion()">${isLast?'See results →':'Next question →'}</button></div></div></div>`,true);
    return;
  }
  openModal(`<div class="quiz-area"><span class="eyebrow">${esc(q.domain)} · ${esc(q.difficulty||'Practice')}</span>${timerHtml}<h2>Question ${state.questionIndex+1} of ${state.questionQueue.length}</h2><div class="quiz-question"><h3>${esc(q.question)}</h3>${(q.options||[]).map((o,i)=>`<button class="quiz-option" onclick="submitAnswer('${esc(q.id)}',${i})">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div class="pager">${prevBtn}<span></span></div></div>`,true);
}
window.submitAnswer=async(id,answer)=>{try{const d=await api('/api/questions/submit',{method:'POST',body:JSON.stringify({id,answer})});if(d.correct)state.quizScore++;state.questionAnswers=state.questionAnswers||{};state.questionAnswers[state.questionIndex]={answer,correct:d.correct,correctAnswer:d.correctAnswer,explanation:d.explanation};showQuizQuestion();state.progress=(await api('/api/me')).progress}catch(e){toast(e.message)}}
function showQuizResult(){clearInterval(state.simTimer);const wasSim=state.simMode;state.simMode=false;const total=state.questionQueue.length;const pct=total?Math.round(state.quizScore/total*100):0;const byDomain=state.progress?.byDomain||{};const domainRows=Object.entries(byDomain).map(([d,v])=>`<div class="compact-row"><b>${esc(d)}</b><small>${v.correct}/${v.answered} correct (${v.answered?Math.round(v.correct/v.answered*100):0}%)</small></div>`).join('');closeModal();openModal(`<div class="quiz-result"><span class="eyebrow">${wasSim?'SIMULATION COMPLETE':'PRACTICE COMPLETE'}</span><h2>${state.quizScore}/${total} · ${pct}%</h2><p>Your results are saved to your progress dashboard.</p>${domainRows?`<h4>Domain performance so far</h4>${domainRows}`:''}<button class="btn primary full" onclick="closeModal();enter('practice')">Back to N&MC Practice</button></div>`,true)}
function downloadQuestions(){if(!premium())return showPremium();location.href='/api/questions/download'}
function renderTutorial(){if(!premium())return renderLocked('Daily Tutorial','Your 7-day Premium trial gives full access to daily syllabus tutorials.');$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">DAILY TUTORIAL</span><h2>One guided lesson every day.</h2><p>Generate a syllabus-based tutorial with objectives, key points, clinical reasoning prompts and original practice questions.</p>${aiModeBadge()}</div><button class="btn primary" id="generateTutorial">Generate today’s tutorial</button></div><div id="tutorialPanel" class="panel"><div class="empty">Click “Generate today’s tutorial” to begin.</div></div>`;$('#generateTutorial').onclick=generateTutorial}
async function generateTutorial(){const btn=$('#generateTutorial');btn.disabled=true;btn.textContent='Generating…';try{const d=await api('/api/ai/daily-tutorial',{method:'POST',body:'{}'});state.tutorial=d.tutorial;$('#tutorialPanel').innerHTML=`<span class="tag">${d.ai?'AI enhanced':'Hub tutorial engine'}</span><h3>${esc(d.tutorial.title)}</h3><h4>Objectives</h4><ul>${(d.tutorial.objectives||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="detail-note"><p>${esc(d.tutorial.lesson||'')}</p></div><h4>Key points</h4><ul>${(d.tutorial.keyPoints||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Practice</h4><ol>${(d.tutorial.practice||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><button class="btn secondary" data-view-go="tutor">Ask AI about today’s tutorial</button>`;afterRender()}catch(e){toast(e.message)}finally{btn.disabled=false;btn.textContent='Generate today’s tutorial'}}
function aiModeBadge(){return state.config?.aiConfigured?'<span class="tag" style="background:#e6f7ee;color:var(--good)">AI Assisted Mode · Active (Live AI)</span>':'<span class="tag" style="background:#eef4f7;color:var(--blue)">AI Assisted Mode · Active (Hub knowledge engine)</span>'}
function renderTutor(){if(!premium())return renderLocked('AI Tutor','The AI Tutor is included in the 7-day full Premium trial and Premium membership.');$('#workspaceContent').innerHTML=`<div class="ai-layout"><section class="panel ai-chat"><div class="panel-head"><div><span class="eyebrow">AI TUTOR</span><h3>Ask until you understand.</h3></div>${aiModeBadge()}</div><div id="aiHistory" class="ai-history"><div class="msg-ai"><b>Hub Tutor</b><p>Ask me to explain a topic, compare concepts, create MCQs, simplify a difficult area or quiz you step-by-step.</p></div></div><form id="aiForm" class="ai-form"><input name="question" placeholder="e.g. Explain pre-eclampsia and why magnesium sulfate is used…" required><button class="btn primary">Ask</button></form></section><aside class="panel"><span class="eyebrow">STUDY CONTEXT</span><h3>Guide the tutor</h3><label class="form-card"><label>Topic<input id="aiTopic" placeholder="e.g. Maternal Health"></label></label><div class="detail-note"><p>The tutor is configured to teach safely, explain rationale, connect concepts to the syllabus and generate original practice questions. It is an educational tool, not a clinical decision-maker.</p></div></aside></div>`;$('#aiForm').onsubmit=askTutor}
async function askTutor(e){e.preventDefault();const fd=new FormData(e.target);const q=String(fd.get('question'));$('#aiHistory').insertAdjacentHTML('beforeend',`<div class="msg-user">${esc(q)}</div><div class="msg-ai" id="thinking"><b>Hub Tutor</b><p>Thinking…</p></div>`);$('#aiHistory').scrollTop=999999;try{state.aiHistory=state.aiHistory||[];state.aiHistory.push({role:'user',text:q});const d=await api('/api/ai/tutor',{method:'POST',body:JSON.stringify({question:q,topic:$('#aiTopic')?.value||'nursing and midwifery',history:state.aiHistory})});const a=d.answer||{};$('#thinking').innerHTML=`<b>Hub Tutor ${d.ai?'· AI':''}</b><p>${esc(a.answer||'')}</p>${a.keyPoints?`<ul>${a.keyPoints.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p><b>Exam tip:</b> ${esc(a.examTip||'')}</p>${a.followUps?`<p><b>Try next:</b> ${esc(a.followUps.join(' · '))}</p>`:''}${a.miniQuiz?`<details><summary>Mini quiz</summary>${a.miniQuiz.map(x=>`<p><b>Q:</b> ${esc(x.question||'')}<br><b>A:</b> ${esc(x.answer||'')}</p>`).join('')}</details>`:''}`;$('#aiHistory').scrollTop=999999}catch(e2){const box=$('#thinking');box.classList.add('msg-error');box.innerHTML=`<b>⚠ Hub Tutor — error</b><p>${esc(e2.message)}</p><button class="btn ghost" style="margin-top:6px" onclick="this.closest('.msg-error').remove()">Dismiss</button>`}}
function renderNutrition(){if(!premium())return renderLocked('Nutrition Course','Your 7-day Premium trial unlocks the full Nutrition course.');const mods=state.content.syllabus.filter(m=>m.track==='Nutrition');$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">NUTRITION COURSE</span><h2>Nutrition for nursing, midwifery and health practice.</h2><p>Learn assessment, dietary foundations, life-stage nutrition, disease-focused nutrition and patient education.</p></div><button class="btn primary" onclick="openModule('${esc(mods[0]?.id||state.content.syllabus[0].id)}')">Start Nutrition</button></div><div class="grid cards-3">${mods.concat(state.content.syllabus.filter(m=>m.title.toLowerCase().includes('nutrition')&&!mods.includes(m))).map(m=>`<article class="course-card"><span class="tag">Nutrition</span><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="topic-list">${m.topics.map(t=>`<span class="topic">${esc(t)}</span>`).join('')}</div><button class="btn secondary full" onclick="openModule('${esc(m.id)}')">Study notes</button></article>`).join('')}</div>`;afterRender()}
function renderJobs(){const jobs=state.content.jobs||[];$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">JOBS & CAREER</span><h2>Read the job before you leave the Hub.</h2><p>Job cards are sourced from verified or administrator-reviewed sources. Open details here; the final application button sends you to the official employer/source page.</p></div><select id="jobCountry" class="field" style="max-width:220px"><option value="">All countries</option>${[...new Set(jobs.map(j=>j.country))].filter(Boolean).map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="grid" id="jobGrid">${jobs.map(j=>jobCard(j)).join('')}</div>`;$('#jobCountry').onchange=()=>{$$('#jobGrid .job-card').forEach(card=>card.style.display=!$('#jobCountry').value||card.dataset.country===$('#jobCountry').value?'':'none')};afterRender()}
function jobCard(j){return `<article class="job-card" data-country="${esc(j.country)}"><div class="job-head"><span class="tag">${j.verified?'Source verified':'Review before applying'}</span><span class="flag">${countryFlag(j.country)}</span></div><h3>${esc(j.title)}</h3><p><b>${esc(j.employer)}</b><br>${esc(j.location||j.country)}</p><div class="meta-row"><span class="meta">${esc(j.type||'Full time')}</span><span class="meta">Closing: ${esc(j.closing?fmtDate(j.closing):'See details')}</span></div><p>${esc(j.summary||'')}</p><div class="job-actions"><button class="btn secondary" onclick="openJob('${esc(j.id)}')">View details</button><button class="btn ghost" onclick="saveJob('${esc(j.id)}')">Save</button></div></article>`}
window.openJob=async id=>{try{const j=await api('/api/jobs/'+id);state.selectedJob=j;openModal(`<div><span class="eyebrow">${esc(j.country)} · ${j.verified?'verified source':'review source'}</span><h2>${esc(j.title)}</h2><p><b>${esc(j.employer)}</b> · ${esc(j.location||'')}</p><div class="meta-row"><span class="meta">${esc(j.type||'')}</span><span class="meta">Closing: ${esc(j.closing?fmtDate(j.closing):'Not stated')}</span><span class="meta">Sponsorship: ${esc(j.sponsorship||'Not stated')}</span></div><div class="detail-note"><h4>Job summary</h4><p>${esc(j.summary||'')}</p><h4>Source</h4><p>${esc(j.source||'')}</p><h4>Application</h4><p>Use the official application link below. Check the employer page for eligibility, closing date, sponsorship and document requirements before submitting.</p></div><div class="job-actions"><button class="btn primary full" onclick="applyOfficial('${esc(j.applicationUrl||'')}','the ${esc(j.title)} role at ${esc(j.employer)}')">Apply on official source →</button><button class="btn secondary full" onclick="saveJob('${esc(j.id)}');closeModal()">Save to career tracker</button></div></div>`,true)}catch(e){toast(e.message)}}
window.promptEvaluationThenOpen=function(url,context){
  if(!/^https?:\/\//i.test(url))return toast('Official application URL is unavailable.');
  openModal(`<span class="eyebrow">BEFORE YOU APPLY</span><h2>Get your documents reviewed first</h2><p>Applying to ${esc(context)}? The Hub's Document Evaluation service checks your transcripts, certificates and profile fit before you spend time on an application, and tells you exactly what's missing.</p><div class="price-features"><span>✓ Reviewed by the Hub team</span><span>✓ Clear next-step recommendation</span><span>✓ ${money(state.config?.evaluationGhs||450)} one-time</span></div><div class="job-actions"><button class="btn primary full" onclick="closeModal();enter('evaluation')">Evaluate (Recommended)</button><button class="btn secondary full" onclick="applyDirectly('${esc(url)}','${esc(context)}');closeModal()">Apply Directly →</button></div>`,false);
}
window.applyOfficial=(url,context='this role')=>promptEvaluationThenOpen(url,context)
window.saveJob=async id=>{try{await api('/api/applications',{method:'POST',body:JSON.stringify({jobId:id})});toast('Saved to Career Tracker.')}catch(e){toast(e.message)}}
function renderTracker(){api('/api/applications').then(items=>{$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">CAREER TRACKER</span><h2>Follow every saved opportunity.</h2><p>Move each application from saved to preparing, applied, interview, offer or closed.</p></div><button class="btn primary" data-view-go="jobs">Find jobs</button></div><div class="grid">${items.length?items.map(x=>{const j=(state.content.jobs||[]).find(y=>y.id===x.jobId);return `<article class="status-card"><h3>${esc(j?.title||x.jobId)}</h3><p>${esc(j?.employer||'')} · ${esc(j?.country||'')}</p><select class="field" data-app-status="${esc(x.id)}"><option value="saved" ${x.status==='saved'?'selected':''}>Saved</option><option value="preparing" ${x.status==='preparing'?'selected':''}>Preparing</option><option value="applied" ${x.status==='applied'?'selected':''}>Applied</option><option value="interview" ${x.status==='interview'?'selected':''}>Interview</option><option value="offer" ${x.status==='offer'?'selected':''}>Offer</option><option value="closed" ${x.status==='closed'?'selected':''}>Closed</option></select></article>`}).join(''):'<div class="empty">No saved opportunities yet.</div>'}</div>`;$$('[data-app-status]').forEach(s=>s.onchange=async()=>{try{await api('/api/applications/'+s.dataset.appStatus,{method:'PATCH',body:JSON.stringify({status:s.value})});toast('Tracker updated.')}catch(e){toast(e.message)}});afterRender()}).catch(e=>toast(e.message))}
function countryFlag(c){return ({Canada:'🇨🇦','United Kingdom':'🇬🇧','New Zealand':'🇳🇿',Australia:'🇦🇺','United States':'🇺🇸',Ghana:'🇬🇭',Germany:'🇩🇪'})[c]||'🌍'}
function renderAbroad(){if(!premium())return renderLocked('Abroad — Study & Work','Your 7-day Premium trial unlocks full country pathways, eligibility criteria and official application guidance. Subscribe after the trial to keep access.');const t=state.content.travel||[];const countries=[...new Set(t.map(x=>x.country))];const study=state.content.studyOptions||[];$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">ABROAD</span><h2>Study Abroad or Work Abroad.</h2><p>Explore country pathways, read the guidance inside the Hub, and use an official application button only when you are ready to apply.</p></div></div><div class="abroad-tabs"><button class="filter-pill active" data-abroad-mode="all">All</button><button class="filter-pill" data-abroad-mode="study">Study Abroad</button><button class="filter-pill" data-abroad-mode="work">Work Abroad</button></div><div class="grid cards-3" id="countryGrid">${countries.map(c=>{const rows=t.filter(x=>x.country===c);return `<article class="country-card" data-country-card="${esc(c)}"><div class="country-top"><div><span class="eyebrow">COUNTRY</span><h3>${esc(c)}</h3></div><div class="flag">${countryFlag(c)}</div></div><p>${rows.map(x=>`<span class="tag">${esc(x.mode==='study'?'Study Abroad':'Work Abroad')}</span>`).join(' ')}</p><div class="pathway-list">${rows.map(x=>`<div class="pathway-item"><strong>${esc(x.title)}</strong><p>${esc((x.steps||[]).slice(0,4).join(' → '))}</p><button class="btn secondary full" onclick="openPathway('${esc(x.id)}')">Read full pathway</button></div>`).join('')}</div></article>`}).join('')}</div><section class="study-finder-section"><div class="panel-head"><div><span class="eyebrow">STUDY ABROAD</span><h3>Institution options to explore</h3><p class="muted">These cards keep the research inside the Hub. The final Apply button opens the institution's official site.</p></div></div><div class="study-option-grid">${study.map(x=>`<article class="study-option"><div class="study-option-head"><span class="flag">${esc(x.flag)}</span><span class="tag">${esc(x.country)}</span></div><h3>${esc(x.institution)}</h3><p>${esc(x.summary)}</p><div class="level-row">${x.levels.map(l=>`<span class="meta">${esc(l)}</span>`).join('')}</div><div class="job-actions"><button class="btn secondary" onclick="openStudyOption('${esc(x.id)}')">View details</button></div></article>`).join('')}</div></section>`;$$('[data-abroad-mode]').forEach(b=>b.onclick=()=>{const mode=b.dataset.abroadMode;$$('[data-abroad-mode]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('#countryGrid .country-card').forEach(card=>{if(mode==='all'){card.style.display=''}else{const c=card.dataset.country;const ok=t.filter(x=>x.country===c).some(x=>x.mode===mode);card.style.display=ok?'':'none'}})});afterRender()}
window.applyDirectly=function(url,context){
  if(!/^https?:\/\//i.test(url))return toast('Official link is unavailable.');
  toast(`Opening ${context} — you are applying directly.`);
  window.open(url,'_blank','noopener,noreferrer');
}
function abroadActionsHtml(applyUrl,context){
  return `<h4>What would you like to do?</h4><p>Applying directly means you leave the Hub to apply with the institution or employer yourself. Evaluation is <b>recommended first</b> — the Hub team checks your documents and profile fit before you spend time on an application.</p><div class="job-actions"><button class="btn primary full" onclick="closeModal();enter('evaluation')">Evaluate (Recommended)</button><button class="btn secondary full" onclick="applyDirectly('${esc(applyUrl)}','${esc(context)}')">Apply Directly →</button></div>`;
}
function criteriaForLevels(levels){
  const map={'Undergraduate':"Completed secondary/high school qualification meeting the institution's entry grades",'Postgraduate':'A relevant undergraduate degree meeting the minimum grade requirement','Doctoral':"A relevant master's degree or equivalent research experience, plus a research proposal"};
  const base=(levels||[]).map(l=>map[l]).filter(Boolean);
  return [...base,'English language proficiency evidence (e.g. IELTS/TOEFL)',"A completed application through the institution's official portal",'A student visa application after a confirmed offer'];
}
window.openPathway=async id=>{try{const t=await api('/api/travel/'+id);const modeLabel=t.mode==='study'?'Study Abroad':'Work Abroad';const criteria=t.criteria||[];openModal(`<span class="eyebrow">${esc(modeLabel)} · ${esc(t.country)}</span><h2>${esc(t.title)}</h2><p class="muted">${esc(t.authority||'')}</p><div class="detail-note"><h4>Route</h4><ol>${(t.steps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${criteria.length?`<h4>Typical eligibility criteria</h4><ul>${criteria.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p class="muted">These are general, commonly required criteria — always confirm the current, exact requirements on the official source below before you apply.</p>`:''}</div><h3>Official sources</h3><div class="pathway-list">${(t.sourceUrls||[]).map(x=>`<div class="pathway-item"><b>${esc(x.name)}</b><p><a class="official-link" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Open official source →</a></p></div>`).join('')}</div>${abroadActionsHtml((t.sourceUrls||[])[0]?.url||'',`the ${t.country} ${modeLabel.toLowerCase()} route`)}`,true)}catch(e){toast(e.message)}}
window.openStudyOption=async id=>{const x=(state.content.studyOptions||[]).find(s=>s.id===id);if(!x)return;const criteria=criteriaForLevels(x.levels);openModal(`<span class="eyebrow">${esc(x.country)} · STUDY ABROAD</span><h2>${esc(x.institution)}</h2><p>${esc(x.summary)}</p><div class="meta-row">${x.levels.map(l=>`<span class="meta">${esc(l)}</span>`).join('')}</div><div class="detail-note"><h4>Typical eligibility criteria</h4><ul>${criteria.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p class="muted">These are general, commonly required criteria — confirm the exact programme, intake, entry requirements, tuition, scholarships and international-student rules on the institution's current official pages.</p><h4>Official programme information</h4><p><a class="official-link" href="${esc(x.officialUrl)}" target="_blank" rel="noopener noreferrer">Open official university programme information →</a></p></div>${abroadActionsHtml(x.applicationUrl||x.officialUrl,`${x.institution} (${x.country})`)}`,true)}

function renderNews(){const news=state.content.news||[];$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">PROFESSIONAL NEWS</span><h2>Read the full Hub story without leaving the platform.</h2><p>News is internally readable with source attribution. Travel and abroad-vacancy stories are a Premium benefit. Auto-imported official-source headlines are refreshed server-side when public feeds are available.</p></div><button class="btn ghost" onclick="location.reload()">Refresh feed</button></div><div class="grid">${news.slice(0,24).map(n=>`<article class="news-card">${n.image?`<img src="${esc(n.image)}" alt="" style="width:100%;height:130px;object-fit:cover;border-radius:12px;margin-bottom:10px">`:''}<span class="tag">${esc(n.category)}</span>${n.locked?'<span class="tag" style="background:#fff2c6;color:#7a5c00;margin-left:6px">🔒 Premium</span>':''}<h3>${esc(n.title)}</h3><p>${esc(n.summary||'')}</p><small>${esc(n.date)} · ${esc(n.source)}</small><button class="btn secondary full" style="margin-top:10px" onclick="openNews('${esc(n.id)}')">Read full Hub article</button></article>`).join('')}</div>`;afterRender()}
window.openNews=async id=>{try{const n=await api('/api/news/'+id);
  if(n.restricted){openModal(`<article class="news-article">${n.image?`<img src="${esc(n.image)}" alt="" style="width:100%;max-height:220px;object-fit:cover;border-radius:14px;margin-bottom:12px">`:''}<span class="tag">${esc(n.category)}</span> <span class="tag" style="background:#fff2c6;color:#7a5c00">🔒 Premium story</span><h2>${esc(n.title)}</h2><p class="muted">${esc(n.date)} · ${esc(n.source)}</p><div class="article-body"><p>${esc(n.teaser||n.summary||'')}</p></div><div class="price-card"><h3>Subscribe to keep reading</h3><p>Travel and abroad-vacancy news is part of Hub Premium, along with Study, Practice, AI Tutor, Community and Abroad pathways.</p><button class="btn primary full" onclick="showPremium()">Unlock Premium</button></div></article>`,true);return;}
  const social=state.user?await api('/api/news/'+id+'/social'):null;openModal(`<article class="news-article">${n.image?`<img src="${esc(n.image)}" alt="" style="width:100%;max-height:220px;object-fit:cover;border-radius:14px;margin-bottom:12px">`:''}<span class="tag">${esc(n.category)}</span><h2>${esc(n.title)}</h2><p class="muted">${esc(n.date)} · ${esc(n.source)}</p><div class="article-body">${(n.body||[n.summary||'']).map(p=>`<p>${esc(p)}</p>`).join('')}</div><p class="muted">Source: ${esc(n.source)}</p><div class="social-row"><button class="btn ghost" id="likeNews">♥ ${social?.count||0}</button>${n.sourceUrl&&/^https?:\/\//i.test(n.sourceUrl)?`<a class="btn ghost" href="${esc(n.sourceUrl)}" target="_blank" rel="noopener noreferrer">Open official source</a>`:''}<span class="muted">Full Hub-authored reading · external source only when you choose to open it.</span></div><div class="panel"><h3>Comments</h3><div id="newsComments" class="comments">${(social?.comments||[]).map(c=>`<div class="comment"><b>${esc(c.author)}</b><br>${esc(c.text)}</div>`).join('')||'<div class="empty">No comments yet.</div>'}</div><form id="newsCommentForm" class="ai-form"><input name="text" placeholder="Add a professional comment…" required><button class="btn primary">Comment</button></form></div></article>`,true);$('#likeNews').onclick=async()=>{const d=await api('/api/news/'+id+'/like',{method:'POST',body:'{}'});$('#likeNews').textContent=`♥ ${d.count}`};$('#newsCommentForm').onsubmit=async e=>{e.preventDefault();const text=new FormData(e.target).get('text');const d=await api('/api/news/'+id+'/comments',{method:'POST',body:JSON.stringify({text})});$('#newsComments').insertAdjacentHTML('beforeend',`<div class="comment"><b>${esc(d.author)}</b><br>${esc(d.text)}</div>`);e.target.reset()}}catch(e){toast(e.message)}}
function renderCommunity(){if(!premium())return renderLocked('Premium Community','Your trial includes the full Premium community. Subscribe after 7 days to keep chatting.');$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">COMMUNITY</span><h2>Connect like a professional social network.</h2><p>Friends, suggestions, direct messages, groups, 24-hour status posts, media attachments and Hub notifications.</p></div><button class="btn primary" onclick="newGroup()">Create group</button></div><div class="community-grid"><aside class="panel"><div class="panel-head"><div><span class="eyebrow">PEOPLE</span><h3>Suggestions</h3></div></div><div id="suggestions" class="people-list"><div class="empty">Loading…</div></div><div class="panel-head" style="margin-top:18px"><div><span class="eyebrow">FRIEND REQUESTS</span><h3>Requests</h3></div></div><div id="pendingRequests" class="people-list"></div><div class="panel-head" style="margin-top:18px"><div><span class="eyebrow">STATUS</span><h3>Stories</h3></div><button class="btn ghost" onclick="postStatus()">＋</button></div><div id="statusList" class="status-row"></div></aside><section class="panel"><div class="panel-head"><div><span class="eyebrow">CHAT</span><h3 id="chatTitle">Community room</h3></div><span id="chatState" class="tag chat-live-tag">Connecting…</span></div><div id="chatMessages" class="chat-messages"></div><form id="chatForm" class="chat-form">${chatToolsHtml('chatForm','chatInput','chatMedia')}<input id="chatInput" placeholder="Share a professional message…"><button class="btn primary">Send</button></form></section><aside class="panel"><div class="panel-head"><div><span class="eyebrow">NETWORK</span><h3>Your people</h3></div></div><div id="friendList" class="people-list"></div><div class="panel-head" style="margin-top:18px"><div><span class="eyebrow">GROUPS</span><h3>Your groups</h3></div></div><div id="groupList" class="group-list"></div></aside></div>`;loadCommunity();}
async function loadCommunity(){try{state.community=await api('/api/community/bootstrap');renderCommunityPeople();renderCommunityChat();renderGroups();initCommunityRealtime()}catch(e){toast(e.message)}}
function personAvatar(p){return `<div class="avatar">${p.avatar?`<img src="${esc(p.avatar)}" alt="${esc(p.name)}">`:esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase())}</div>`}
function renderCommunityPeople(){const s=state.community||{};$('#suggestions').innerHTML=(s.people||[]).filter(p=>!s.friends?.some(f=>f.otherUserId===p.id)).slice(0,10).map(p=>`<div class="person">${personAvatar(p)}<div><strong>${esc(p.name)}</strong><small>${esc(p.profession||profileRole())}</small></div><button class="btn secondary" onclick="addFriend('${esc(p.id)}')">Add</button></div>`).join('')||'<div class="empty">No new suggestions yet.</div>';$('#pendingRequests').innerHTML=(s.pendingRequests||[]).map(f=>`<div class="person">${personAvatar(f.otherUser)}<div><strong>${esc(f.otherUser?.name||'Member')}</strong><small>Wants to connect</small></div><button class="btn secondary" onclick="respondFriend('${esc(f.id)}','accept')">Accept</button><button class="btn ghost" onclick="respondFriend('${esc(f.id)}','decline')">Decline</button></div>`).join('')||'<div class="empty">No pending requests.</div>';$('#friendList').innerHTML=(s.friends||[]).filter(x=>x.status==='accepted').map(f=>`<div class="person">${personAvatar(f.otherUser)}<div><strong>${esc(f.otherUser?.name||'Connected member')}</strong><small>${esc(f.otherUser?.profession||'Member')} · ${f.otherUser?.friendsCount||0} connections</small></div><button class="btn ghost" onclick="openDirect('${esc(f.otherUserId)}')">Chat</button></div>`).join('')||'<div class="empty">No friends yet.</div>';$('#statusList').innerHTML=(s.statuses||[]).map(x=>`<button class="status-card" onclick="viewStatus('${esc(x.id)}')">${personAvatar(x.user)}<span>${esc(x.user?.name||'Member')}</span></button>`).join('')||'<div class="empty">No active statuses.</div>'} 
function renderCommunityChat(){const box=$('#chatMessages');if(!box)return;const messages=state.community?.messages||[];box.innerHTML=messages.map(m=>chatBubble(m)).join('')||'<div class="empty">Community messages appear here. Say hello.</div>';box.scrollTop=999999;$('#chatForm').onsubmit=sendCommunityMessage}
const EMOJI_LIST=['😊','👍','❤️','🙏','🎉','📚','🩺','👏','💪','🔥','✅','❗','📌','🕐','📷','🎓','🤝','😢','😃','🙌','⭐','💬','🧠','💉','🌍','✈️','📖','🥳','😴','🤔'];
const STICKER_LIST=[{e:'🩺',t:'On it'},{e:'🎓',t:'Graduated'},{e:'👏',t:'Well done'},{e:'🙌',t:'Celebrate'},{e:'📚',t:'Studying'},{e:'✅',t:'Done'},{e:'🔥',t:'On a streak'},{e:'🤝',t:'Support'},{e:'🌍',t:'Abroad'},{e:'❤️',t:'Love it'},{e:'💪',t:'You got this'},{e:'🥳',t:'Celebration'}];
function chatToolsHtml(formId,inputId,mediaId){const attach=mediaId?`<label class="chat-tool-btn attach-btn" title="Attach photo, audio or video">📎<input id="${mediaId}" type="file" accept="image/*,audio/*,video/*" hidden></label>`:'';return `${attach}<button type="button" class="chat-tool-btn emoji-btn" title="Emoji" onclick="toggleEmojiPicker('${inputId}',this)">🙂</button><button type="button" class="chat-tool-btn sticker-btn" title="Stickers" onclick="toggleStickerPicker('${formId}','${inputId}',this)">✨</button>`}
function closePickers(){$$('.picker-popover').forEach(p=>p.remove());window.__activePicker=null}
function positionPopover(pop,btn){document.body.appendChild(pop);const r=btn.getBoundingClientRect();const top=Math.max(8,r.top-pop.offsetHeight-8);let left=r.left;if(left+pop.offsetWidth>window.innerWidth-8)left=window.innerWidth-pop.offsetWidth-8;pop.style.left=Math.max(8,left)+'px';pop.style.top=top+'px'}
function toggleEmojiPicker(inputId,btn){const key='emoji-'+inputId;if(window.__activePicker===key){closePickers();return}closePickers();const pop=document.createElement('div');pop.className='picker-popover emoji-popover';pop.innerHTML=EMOJI_LIST.map(e=>`<button type="button" onclick="insertEmoji('${inputId}','${e}')">${e}</button>`).join('');positionPopover(pop,btn);window.__activePicker=key}
function toggleStickerPicker(formId,inputId,btn){const key='sticker-'+inputId;if(window.__activePicker===key){closePickers();return}closePickers();const pop=document.createElement('div');pop.className='picker-popover sticker-popover';pop.innerHTML=STICKER_LIST.map(s=>`<button type="button" title="${esc(s.t)}" onclick="sendSticker('${formId}','${inputId}','${s.e}')">${s.e}</button>`).join('');positionPopover(pop,btn);window.__activePicker=key}
function insertEmoji(inputId,e){const el=document.getElementById(inputId);if(el){el.value+=e;el.focus()}closePickers()}
function sendSticker(formId,inputId,emoji){const el=document.getElementById(inputId);if(el)el.value=emoji;closePickers();const form=document.getElementById(formId);if(form)form.requestSubmit?form.requestSubmit():form.dispatchEvent(new Event('submit',{cancelable:true}))}
if(!window.__pickerOutsideClickBound){window.__pickerOutsideClickBound=true;document.addEventListener('click',e=>{if(window.__activePicker&&!e.target.closest('.picker-popover')&&!e.target.closest('.emoji-btn')&&!e.target.closest('.sticker-btn'))closePickers()});}
function isStickerText(text){const t=String(text||'').trim();return t!==''&&t.length<=6&&!/[a-zA-Z0-9]/.test(t)}
function chatBubble(m,scope='community'){const media=m.media?`<a class="official-link" href="/api/community/media/${scope}/${esc(m.id)}" target="_blank" rel="noopener noreferrer">View attachment</a>`:'';const text=String(m.text||'');const sticker=isStickerText(text);return `<div class="bubble ${m.userId===state.user.id?'me':'other'}"><b>${esc(m.author||'Member')}</b><div${sticker?' class="sticker-msg"':''}>${esc(text)}</div>${media}<small class="muted">${esc(new Date(m.createdAt).toLocaleTimeString())}</small></div>`}
function initCommunityRealtime(){if(state.ws||!premium())return;try{state.ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws`);state.ws.onopen=()=>{const s=$('#chatState');if(s){s.innerHTML='<span class="live-dot"></span> Live'}};state.ws.onclose=()=>{const s=$('#chatState');if(s)s.textContent='Reconnect';state.ws=null};state.ws.onmessage=e=>{const m=JSON.parse(e.data);handleRealtime(m)}}catch{}}
function handleRealtime(m){if(m.type==='message'&&state.view==='community'){state.community=state.community||{};state.community.messages=state.community.messages||[];state.community.messages.push(m.data);renderCommunityChat();notifySound();}if(m.type==='notification'){state.notifications.unshift(m.data);updateNotifyCount();notifySound();browserNotify(m.data.title,m.data.text)}if(m.type==='direct_message'||m.type==='support_message'){notifySound();browserNotify('New message',m.data?.text||'');}}
function notifySound(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=740;g.gain.value=.03;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.11)}catch{}}
function browserNotify(title,text){if('Notification' in window&&Notification.permission==='granted')new Notification(title,{body:text});}
async function requestNotifications(){if('Notification' in window&&Notification.permission==='default')await Notification.requestPermission()}
async function sendCommunityMessage(e){e.preventDefault();const text=$('#chatInput').value.trim(),file=$('#chatMedia').files[0];if(!text&&!file)return;try{const fd=new FormData();fd.append('text',text);if(file)fd.append('media',file);const d=await api('/api/community/messages',{method:'POST',body:fd});state.community=state.community||{};state.community.messages=state.community.messages||[];state.community.messages.push(d);renderCommunityChat();$('#chatInput').value='';$('#chatMedia').value='';}catch(e2){toast(e2.message)}}
async function addFriend(id){try{await api('/api/community/friends',{method:'POST',body:JSON.stringify({friendId:id})});toast('Friend request sent.')}catch(e){toast(e.message)}}
async function respondFriend(id,action){try{await api('/api/community/friends/'+id+'/respond',{method:'POST',body:JSON.stringify({action})});await loadCommunity();toast(action==='accept'?'Connection accepted.':'Request declined.')}catch(e){toast(e.message)}}
window.openDirect=async id=>{state.selectedPerson=(state.community?.people||[]).find(p=>p.id===id)||null;if(!state.selectedPerson){const me=await api('/api/community/people');state.selectedPerson=me.suggestions.find(p=>p.id===id)};const rows=await api('/api/community/direct/'+id);openModal(`<span class="eyebrow">PRIVATE CHAT</span><h2>${esc(state.selectedPerson?.name||'Member')}</h2><div id="directMessages" class="chat-messages">${rows.map(m=>chatBubble(m,'direct')).join('')||'<div class="empty">Start a private conversation.</div>'}</div><form id="directForm" class="chat-form">${chatToolsHtml('directForm','directInput','directMedia')}<input id="directInput" placeholder="Write a private message…"><button class="btn primary">Send</button></form>`,true);$('#directForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData();fd.append('toId',id);fd.append('text',$('#directInput').value);if($('#directMedia').files[0])fd.append('media',$('#directMedia').files[0]);try{const d=await api('/api/community/direct',{method:'POST',body:fd});$('#directMessages').insertAdjacentHTML('beforeend',chatBubble(d,'direct'));$('#directInput').value=''}catch(er){toast(er.message)}}}
function newGroup(){openModal(`<span class="eyebrow">NEW GROUP</span><h2>Create a professional study group</h2><form id="groupForm" class="form-card"><label>Group name<input name="name" required></label><label>Description<textarea name="description"></textarea></label><button class="btn primary full">Create group</button></form>`);$('#groupForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/community/groups',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();loadCommunity();toast('Group created.')}catch(er){toast(er.message)}}}
function renderGroups(){const el=$('#groupList');if(!el)return;el.innerHTML=(state.community?.groups||[]).map(g=>`<div class="group-card"><div><strong>${esc(g.name)}</strong><small>${esc(g.members||1)} members</small></div><button class="btn ghost" onclick="openGroup('${esc(g.id)}')">Open</button></div>`).join('')||'<div class="empty">Create your first group.</div>'}
window.openGroup=async id=>{const g=(state.community?.groups||[]).find(x=>x.id===id);const rows=await api('/api/community/group/'+id+'/messages');openModal(`<span class="eyebrow">GROUP</span><h2>${esc(g?.name||'Group')}</h2><p>${esc(g?.description||'')}</p><div id="groupMessages" class="chat-messages">${rows.map(m=>chatBubble(m,'group')).join('')}</div><form id="groupFormChat" class="chat-form">${chatToolsHtml('groupFormChat','groupInput','groupMedia')}<input id="groupInput" placeholder="Message the group…"><button class="btn primary">Send</button></form>` ,true);$('#groupFormChat').onsubmit=async e=>{e.preventDefault();const file=$('#groupMedia').files[0];try{const fd=new FormData();fd.append('text',$('#groupInput').value);if(file)fd.append('media',file);const d=await api('/api/community/group/'+id+'/messages',{method:'POST',body:fd});$('#groupMessages').insertAdjacentHTML('beforeend',chatBubble(d,'group'));$('#groupInput').value='';$('#groupMedia').value=''}catch(er){toast(er.message)}}}
function postStatus(){openModal(`<span class="eyebrow">YOUR STATUS</span><h2>Share a 24-hour update</h2><form id="statusForm" class="form-card"><label>Text<textarea name="text" maxlength="500" placeholder="Share a study, career or professional update…"></textarea></label><label>Photo, audio or short video<input name="media" type="file" accept="image/*,audio/*,video/*"></label><button class="btn primary full">Post status</button></form>`);$('#statusForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);try{await api('/api/community/status',{method:'POST',body:fd});closeModal();loadCommunity();toast('Status posted for 24 hours.')}catch(er){toast(er.message)}}}
window.viewStatus=async id=>{openModal(`<div class="empty">Loading status…</div>`);try{const rows=state.community.statuses||[];const s=rows.find(x=>x.id===id);let media='';if(s?.media){const src=`/api/community/media/status/${esc(id)}`;if(String(s.media.mime||'').startsWith('image/'))media=`<img class="status-media" src="${src}" alt="Status media">`;else if(String(s.media.mime||'').startsWith('audio/'))media=`<audio controls src="${src}"></audio>`;else media=`<video controls class="status-media" src="${src}"></video>`;}openModal(`<span class="eyebrow">STATUS</span><h2>${esc(s?.user?.name||'Member')}</h2><p>${esc(s?.text||'')}</p>${media}<small class="muted">Expires in 24 hours.</small>`)}catch(e){toast(e.message)}}
function renderEvaluation(){
  loadEvaluations().then(()=>{
    const ready=state.lastEvalPayment;const itemsHtml=(state.evalItems||[]).map(x=>`<div class="status-card"><b>${esc(x.reference)}</b><span>${esc(x.targetCountry)} · ${esc(x.pathwayType)} · <span class="eval-status">${esc(x.status)}</span></span><small>${esc(x.recommendation?.title||'Review in progress')}</small></div>`).join('');$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">DOCUMENT EVALUATION</span><h2>Professional review for Job Abroad or School Abroad.</h2><p>Pay the GHS 450 evaluation fee, submit your documents, then receive the review outcome. Official application routes are released only after review.</p></div><span class="tag">GHS 450</span></div><div class="grid two"><section class="price-card"><span class="eyebrow">HOW IT WORKS</span><h3>One evaluation, clear next step.</h3><p>1. Pay GHS 450 through the Hub. 2. Complete your profile and upload documents. 3. Admin reviews the submission. 4. Your outcome and appropriate official route are released.</p>${ready?'<div class="notice">Evaluation payment verified. You can submit your form.</div>':'<button class="btn primary full" onclick="startPayment(\'transcript\')">Pay GHS 450 & continue</button>'}</section><section class="panel"><span class="eyebrow">YOUR SUBMISSIONS</span><h3>Evaluation history</h3>${itemsHtml||'<div class="empty">No evaluation submissions yet.</div>'}</section></div>${ready?evaluationForm():''}`;
    const ef=$('#evaluationForm'); if(ef)ef.onsubmit=submitEvaluationForm;
    afterRender();
  });
}
async function submitEvaluationForm(e){
  e.preventDefault();
  const form=e.target,btn=form.querySelector('button');
  if(btn){btn.disabled=true;btn.textContent='Submitting…';}
  try{
    const fd=new FormData(form);
    const d=await api('/api/transcript-evaluation',{method:'POST',body:fd});
    state.lastEvalPayment='';
    toast(`Evaluation submitted. Reference ${d.reference}. The Hub team will review it.`);
    renderEvaluation();
  }catch(err){
    toast(err.message);
    if(btn){btn.disabled=false;btn.textContent='Submit evaluation';}
  }
}
function evaluationForm(){const inst=state.user?.institution||'';return `<section class="panel" style="margin-top:15px"><div class="panel-head"><div><span class="eyebrow">SECURE SUBMISSION</span><h3>Document Evaluation Form</h3></div></div><form id="evaluationForm" class="form-card" enctype="multipart/form-data"><div class="auth-grid"><label>Full name<input name="fullName" value="${esc(state.user.name)}" required></label><label>Email<input name="email" value="${esc(state.user.email)}" type="email" required></label></div><div class="auth-grid"><label>Profession<select name="profession"><option>Nursing</option><option>Midwifery</option><option>Nutritionist</option><option>Public Health</option></select></label><label>Institution<input name="institution" value="${esc(inst)}" required></label></div><div class="auth-grid"><label>Qualification<input name="qualification" required></label><label>Graduation year<input name="graduationYear" type="number" min="1950" max="2100"></label></div><div class="auth-grid"><label>Target destination<input name="targetCountry" placeholder="e.g. UK, Canada, Australia" required></label><label>Purpose<select name="pathwayType"><option value="work">Job Abroad</option><option value="study">School Abroad</option></select></label></div><div class="auth-grid"><label>Specialty<input name="specialty" placeholder="Optional"></label><label>Experience years<input name="experienceYears"></label></div><label>English / language status<input name="englishStatus" placeholder="Optional"></label><div class="auth-grid"><label>Transcript<input name="transcript" type="file" accept="application/pdf,image/jpeg,image/png" required></label><label>Certificate<input name="certificate" type="file" accept="application/pdf,image/jpeg,image/png"></label></div><div class="auth-grid"><label>Registration / good standing<input name="registration" type="file" accept="application/pdf,image/jpeg,image/png"></label><label>Government ID<input name="idDocument" type="file" accept="application/pdf,image/jpeg,image/png"></label></div><label>CV / résumé<input name="cv" type="file" accept="application/pdf,image/jpeg,image/png"></label><label>Additional information<textarea name="notes" rows="5"></textarea></label><input type="hidden" name="paymentReference" value="${esc(state.lastEvalPayment)}"><button class="btn primary xl">Submit evaluation</button></form></section>`}
async function loadEvaluations(){try{state.evalItems=await api('/api/transcript-evaluation')}catch{} }
function renderReels(){
  api('/api/reels').then(reels=>{
    state.reels=reels;
    $('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">REELS</span><h2>Entertainment for every Hub member.</h2><p>Quick tips, wins and moments from the Hub community — visible to every account holder, Premium or not. Post your own below.</p></div><button class="btn primary" onclick="postReel()">Post a Reel</button></div><div class="reel-grid" id="reelGrid">${reels.map(reelCard).join('')||'<div class="empty">No reels yet — be the first to post one.</div>'}</div>`;
    afterRender();
  }).catch(e=>toast(e.message));
}
function reelCard(r){
  const media=r.mediaType==='video'?`<video controls class="reel-media" src="${esc(r.mediaUrl)}"></video>`:r.mediaType==='audio'?`<div class="reel-media reel-audio"><audio controls src="${esc(r.mediaUrl)}"></audio></div>`:`<img class="reel-media" src="${esc(r.mediaUrl)}" alt="Reel">`;
  return `<article class="reel-card">${media}<div class="reel-body"><b>${esc(r.author)}</b><p>${esc(r.caption||'')}</p><button class="btn ghost" onclick="toggleReelLike('${esc(r.id)}')">${r.liked?'♥':'♡'} ${r.likeCount}</button></div></article>`;
}
window.toggleReelLike=async id=>{try{await api('/api/reels/'+id+'/like',{method:'POST',body:'{}'});renderReels()}catch(e){toast(e.message)}}
function postReel(){openModal(`<span class="eyebrow">POST A REEL</span><h2>Share a photo, video or audio moment</h2><form id="reelForm" class="form-card" enctype="multipart/form-data"><label>Caption<textarea name="caption" maxlength="300" placeholder="What's this about?"></textarea></label><label>Photo, audio or video<input name="media" type="file" accept="image/*,audio/*,video/*" required></label><button class="btn primary full">Post Reel</button></form>`);$('#reelForm').onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target);await api('/api/reels',{method:'POST',body:fd});closeModal();toast('Reel posted.');renderReels()}catch(er){toast(er.message)}}}
function renderStories(){const stories=state.content.stories||[];$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">MEMBER STORIES</span><h2>Real experiences, published with consent.</h2><p>Members can share N&MC preparation, study-abroad or work-abroad experiences. Anonymous publication is supported.</p></div><button class="btn primary" onclick="shareStory()">Share my story</button></div><div class="grid cards-3">${stories.map(s=>`<article class="story-card"><span class="tag">${esc(s.type)}</span><p class="story-quote">“${esc(s.text)}”</p><small>${esc(s.name)}</small></article>`).join('')||'<div class="empty">Genuine experiences will appear here after consent and moderation.</div>'}</div>`;afterRender()}
function shareStory(){openModal(`<span class="eyebrow">MEMBER STORY</span><h2>Share your experience</h2><form id="storyForm" class="form-card"><label>Experience type<select name="type"><option>N&MC preparation</option><option>Study Abroad</option><option>Work Abroad</option><option>Career growth</option></select></label><label>Your story<textarea name="text" minlength="30" required></textarea></label><label><input type="checkbox" name="anonymous" checked> Publish anonymously</label><label><input type="checkbox" name="consent" required> I consent to publication after moderation.</label><button class="btn primary full">Submit story</button></form>`);$('#storyForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);try{await api('/api/stories',{method:'POST',body:JSON.stringify({type:fd.get('type'),text:fd.get('text'),anonymous:fd.get('anonymous')==='on',consent:fd.get('consent')==='on'})});closeModal();toast('Story submitted for moderation.')}catch(er){toast(er.message)}}}
function renderEnquiries(){if(!state.user){showLogin();return}api('/api/enquiries').then(items=>{$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">ENQUIRIES & SUPPORT</span><h2>Ask the Hub team.</h2><p>Use the enquiry system for study, N&MC preparation, jobs, abroad pathways, document evaluation or account issues.</p></div><button class="btn secondary" onclick="openSupportChat()">Message support</button></div><div class="grid two"><section class="panel"><h3>New enquiry</h3><form id="enquiryForm" class="form-card"><label>Subject<input name="subject" required></label><label>Message<textarea name="message" rows="7" required></textarea></label><button class="btn primary full">Submit enquiry</button></form></section><section class="panel"><h3>Your enquiries</h3>${items.map(x=>`<div class="status-card"><b>${esc(x.reference)}</b><span>${esc(x.subject)} · ${esc(x.status)}</span><small>${esc(x.message)}</small></div>`).join('')||'<div class="empty">No enquiries yet.</div>'}</section></div>`;$('#enquiryForm').onsubmit=submitEnquiry})}
async function submitEnquiry(e){e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));data.name=state.user?.name||data.name;data.email=state.user?.email||data.email;const d=await api('/api/enquiries',{method:'POST',body:JSON.stringify(data)});e.target.reset();toast(`Enquiry ${d.reference} received.`);renderEnquiries()}catch(err){toast(err.message)}}
function supportBubble(m){return `<div class="bubble ${m.sender==='member'?'me':'other'}"><b>${m.sender==='admin'?'Hub Admin':'You'}</b><div${isStickerText(m.text)?' class="sticker-msg"':''}>${esc(m.text)}</div></div>`}
async function openSupportChat(){const rows=await api('/api/support/messages');openModal(`<span class="eyebrow">HUB SUPPORT</span><h2>Message Hub Admin</h2><div id="supportMessages" class="chat-messages">${rows.map(supportBubble).join('')||'<div class="empty">Start a support conversation.</div>'}</div><form id="supportForm" class="chat-form">${chatToolsHtml('supportForm','supportInput')}<input id="supportInput" required placeholder="Write to Hub Admin…"><button class="btn primary">Send</button></form>`,true);$('#supportForm').onsubmit=async e=>{e.preventDefault();const d=await api('/api/support/messages',{method:'POST',body:JSON.stringify({text:$('#supportInput').value})});$('#supportMessages').insertAdjacentHTML('beforeend',supportBubble({sender:'member',text:d.text}));$('#supportInput').value=''}}
function renderProfile(){const t=trialInfo();const insts=(state.content.institutions||[]).map(x=>`<option ${state.user.institution===x.name?'selected':''}>${esc(x.name)}</option>`).join('');$('#workspaceContent').innerHTML=`<div class="view-intro"><div><span class="eyebrow">PROFILE</span><h2>${esc(state.user.name)}</h2><p>${esc(state.user.profession)} · ${profileRole()}</p></div><button class="btn ghost" data-action="signout">Sign out</button></div><div class="grid two"><section class="panel"><h3>Your profile</h3><form id="profileForm" class="form-card"><label>Profile photo<input id="avatarUpload" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Full name<input name="name" value="${esc(state.user.name)}"></label><label>Profession<select name="profession">${['Nursing','Midwifery','Nutritionist','Public Health','Community Health Nursing','Mental Health Nursing'].map(x=>`<option ${state.user.profession===x?'selected':''}>${x}</option>`).join('')}</select></label>${state.user.role==='student'?`<label>Training college / university<select name="institution">${insts}</select></label><label>Study level<select name="studyLevel">${STUDY_LEVELS.map(x=>`<option ${state.user.studyLevel===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Programme<select name="programme">${PROGRAMMES.map(x=>`<option ${state.user.programme===x?'selected':''}>${x}</option>`).join('')}</select></label>`:''}<button class="btn primary full">Save profile</button></form></section><section class="panel"><span class="eyebrow">MEMBERSHIP</span><h3>${membership()}</h3><p>${state.user.subscription?.active?`Your ${money(state.config?.subscriptionGhs||50)}/month Premium membership is active.`:t.active?`You have full access for ${t.days} day(s), ${t.hours} hour(s) and ${t.minutes} minute(s).`:'Premium is locked.'}</p><div class="price-features"><span>✓ Study + notes</span><span>✓ N&MC practice</span><span>✓ AI Tutor</span><span>✓ Daily tutorial</span><span>✓ Nutrition</span><span>✓ Community</span></div><button class="btn primary full" data-action="subscribe">${state.user.subscription?.active?'Premium active':money(state.config?.subscriptionGhs||50)+'/month'}</button><button class="btn secondary full" onclick="showPaymentHistory()">Payment history</button><button class="btn ghost full" onclick="showForgotPassword()">Reset password</button></section></div>`;$('#profileForm').onsubmit=saveProfile;$('#avatarUpload').onchange=uploadAvatar;afterRender()}
async function saveProfile(e){e.preventDefault();try{state.user=await api('/api/profile',{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});syncUserUI();toast('Profile saved.')}catch(e2){toast(e2.message)}}
async function uploadAvatar(e){const f=e.target.files[0];if(!f)return;try{const fd=new FormData();fd.append('avatar',f);state.user=await api('/api/profile/avatar',{method:'POST',body:fd});syncUserUI();toast('Profile photo updated.')}catch(er){toast(er.message)}}
async function showPaymentHistory(){try{const rows=await api('/api/payments/history');openModal(`<span class="eyebrow">PAYMENTS</span><h2>Payment history</h2><div class="comments">${rows.map(x=>`<div class="comment"><b>${esc(x.purpose)}</b> · ${esc(x.status)}<br>${money(x.amount)} · ${esc(x.currency)}<br><small>${esc(x.reference)}</small></div>`).join('')||'<div class="empty">No payments yet.</div>'}</div>`,false)}catch(e){toast(e.message)}}
function renderLocked(title,text){$('#workspaceContent').innerHTML=`<section class="price-card"><span class="eyebrow">PREMIUM</span><h2>${esc(title)}</h2><p>${esc(text)}</p><div class="price-features"><span>✓ Full study + notes</span><span>✓ N&MC practice</span><span>✓ AI Tutor</span><span>✓ Daily tutorials</span><span>✓ Nutrition</span><span>✓ Community</span></div><button class="btn primary" onclick="showPremium">Subscribe</button></section>`;$('#workspaceContent button').onclick=showPremium}
function showPremium(){const t=trialInfo();openModal(`<span class="eyebrow">HUB PREMIUM</span><h2>7 days free. Then ${money(state.config?.subscriptionGhs||50)}/month.</h2><p>${t.active?`Your full-access trial is running: ${t.days}d ${t.hours}h ${t.minutes}m ${t.seconds}s remaining.`:'Your free Premium trial has ended. Subscribe to reopen Premium.'}</p><div class="price-features"><span>✓ All Study modules + progress</span><span>✓ N&MC MCQs + theory + downloads</span><span>✓ AI Tutor + Daily Tutorial</span><span>✓ Nutrition course</span><span>✓ Jobs + Career Tracker</span><span>✓ Abroad study + work guidance</span><span>✓ Premium Community</span><span>✓ News, comments and member stories</span></div>${state.user?.subscription?.active?'<div class="notice">Premium is active.</div>':`<button class="btn primary full" onclick="startPayment('subscription')">Subscribe · ${money(state.config?.subscriptionGhs||50)}/month</button>`}`,false)}
async function startPayment(purpose){if(!state.user)return showLogin();try{const d=await api('/api/payments/initialize',{method:'POST',body:JSON.stringify({purpose})});location.href=d.authorization_url}catch(e){toast(e.message)}}
async function handlePaymentCallback(){const p=new URLSearchParams(location.search),ref=p.get('reference')||p.get('trxref'),route=p.get('route');if(!ref||route!=='payment-result')return;try{const d=await api('/api/payments/verify/'+encodeURIComponent(ref));if(d.purpose==='subscription'){state.user=d.user;state.lastEvalPayment=''}else{state.lastEvalPayment=ref}const me=await api('/api/me');state.user=me.user;state.progress=me.progress;state.csrf=me.csrf;history.replaceState({},'',location.pathname);enter(d.purpose==='transcript'?'evaluation':'dashboard');toast(d.purpose==='subscription'?'Premium activated.':'GHS 450 payment verified. Complete your document evaluation.')}catch(e){toast(e.message)}}
function showLogin(){openModal(`<span class="eyebrow">YOUR HUB ACCOUNT</span><h2>Sign in</h2><form id="loginForm" class="form-card"><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button class="btn primary full">Sign in</button><button type="button" class="link-button" onclick="showForgotPassword()">Forgot password?</button><button type="button" class="btn secondary full" onclick="showSignup('student')">Create student account</button><button type="button" class="btn ghost full" onclick="showSignup('graduate')">Create graduate/professional account</button></form>`);$('#loginForm').onsubmit=loginSubmit}
async function loginSubmit(e){e.preventDefault();try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.user=d.user;state.csrf=d.csrf;state.progress=(await api('/api/me')).progress;state.notifications=await api('/api/notifications').catch(()=>[]);updateNotifyCount();closeModal();enter(state.pendingView||'dashboard');state.pendingView=null;startTrialClock();toast(`Welcome back, ${state.user.name.split(' ')[0]}.`);requestNotifications();}catch(e2){toast(e2.message)}}
const STUDY_LEVELS=['Year 1','Year 2','Year 3','Year 4'];
const PROGRAMMES=['General Nursing (RGN)','Midwifery (RM)','Public Health Nursing','Community Health Nursing','Mental Health Nursing','Nutrition and Dietetics'];
function showSignup(role){const instOptions=(state.content.institutions||[]).map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join('');const professions=['Nursing','Midwifery','Nutritionist','Public Health','Community Health Nursing','Mental Health Nursing'];openModal(`<span class="eyebrow">CREATE ACCOUNT</span><h2>${role==='student'?'Student':'Graduate / Professional'} profile</h2><div class="auth-grid"><button id="studentRole" class="role-choice ${role==='student'?'active':''}">🎓 Student</button><button id="graduateRole" class="role-choice ${role==='graduate'?'active':''}">🩺 Graduate / Professional</button></div><form id="signupForm" class="form-card" style="margin-top:12px"><label>Full name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="8" required></label><label>Profession<select name="profession">${professions.map(x=>`<option>${x}</option>`).join('')}</select></label>${role==='student'?`<label>University / training college<select name="institution" required><option value="">Select institution</option>${instOptions}</select></label><label>Study level<select name="studyLevel" required><option value="">Select year</option>${STUDY_LEVELS.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Programme / qualification<select name="programme" required><option value="">Select programme</option>${PROGRAMMES.map(x=>`<option>${x}</option>`).join('')}</select></label>`:''}<input type="hidden" name="role" value="${role}"><button class="btn primary full">Create account + start 7-day Premium trial</button></form>`);$('#studentRole').onclick=()=>showSignup('student');$('#graduateRole').onclick=()=>showSignup('graduate');$('#signupForm').onsubmit=signupSubmit}
async function signupSubmit(e){e.preventDefault();try{const d=await api('/api/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.user=d.user;state.csrf=d.csrf;state.progress=(await api('/api/me')).progress;state.notifications=await api('/api/notifications').catch(()=>[]);updateNotifyCount();closeModal();enter(state.pendingView||'dashboard');state.pendingView=null;startTrialClock();toast('Your 7-day full Premium trial has started.');requestNotifications();}catch(e2){toast(e2.message)}}
function showForgotPassword(){openModal(`<span class="eyebrow">ACCOUNT RECOVERY</span><h2>Reset your password</h2><p>For local development the reset link is shown here. In production connect this to your transactional email provider.</p><form id="forgotForm" class="form-card"><label>Email<input name="email" type="email" required></label><button class="btn primary full">Send reset link</button></form>`);$('#forgotForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/forgot-password',{method:'POST',body:JSON.stringify({email:new FormData(e.target).get('email')})});if(d.devResetUrl)openModal(`<span class="eyebrow">RESET LINK</span><h2>Development reset link</h2><a class="btn primary full" href="${esc(d.devResetUrl)}">Open reset page</a>`);else toast(d.message)}catch(er){toast(er.message)}}}
function renderResetFromUrl(){const p=new URLSearchParams(location.search);if(!p.get('reset')||!p.get('email'))return;openModal(`<span class="eyebrow">RESET PASSWORD</span><h2>Choose a new password</h2><form id="resetForm" class="form-card"><label>New password<input name="password" type="password" minlength="8" required></label><label>Confirm password<input name="confirm" type="password" minlength="8" required></label><button class="btn primary full">Reset password</button></form>`);$('#resetForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);if(fd.get('password')!==fd.get('confirm'))return toast('Passwords do not match.');try{await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify({email:p.get('email'),token:p.get('reset'),password:fd.get('password')})});history.replaceState({},'',location.pathname);closeModal();showLogin();toast('Password updated.')}catch(er){toast(er.message)}}}
async function signOut(){try{await api('/api/auth/logout',{method:'POST',body:'{}'});location.reload()}catch(e){toast(e.message)}}
function updateNotifyCount(){const n=(state.notifications||[]).filter(x=>!x.read).length;$('#notifyCount').textContent=n;$('#notifyCount').style.display=n?'block':'none'}
function showNotifications(){const rows=(state.notifications||[]).slice(0,30);openModal(`<span class="eyebrow">NOTIFICATIONS</span><h2>Updates</h2>${rows.map(n=>`<button class="comment ${n.read?'':'notif-unread'}" style="width:100%;text-align:left" onclick="readNotification('${esc(n.id)}')">${n.read?'':'<span class="unread-dot"></span>'}<b>${esc(n.title)}</b><br>${esc(n.text)}<br><small>${esc(new Date(n.createdAt).toLocaleString())}</small></button>`).join('')||'<div class="empty">No notifications.</div>'}`);}
window.readNotification=async id=>{try{await api('/api/notifications/'+id+'/read',{method:'POST',body:'{}'});state.notifications=state.notifications.map(x=>x.id===id?{...x,read:true}:x);updateNotifyCount();showNotifications()}catch(e){toast(e.message)}}
window.jumpToQuestion=function(id){closeModal();if(!premium())return showPremium();const all=state.content.questions||[];const index=all.findIndex(x=>x.id===id);if(index<0)return;const setIndex=Math.floor(index/10);enter('practice');setTimeout(()=>{startPractice(setIndex);state.questionIndex=index%10;showQuizQuestion();},80);}
function searchAll(q){if(!q)return;const lower=q.toLowerCase();const study=state.content.syllabus.filter(x=>(x.title+' '+x.description+' '+x.topics.join(' ')).toLowerCase().includes(lower)).slice(0,6);const questions=(state.content.questions||[]).filter(x=>(x.question+' '+x.domain).toLowerCase().includes(lower)).slice(0,6);const jobs=state.content.jobs.filter(x=>(x.title+' '+x.employer+' '+x.country).toLowerCase().includes(lower)).slice(0,6);const news=state.content.news.filter(x=>(x.title+' '+x.summary).toLowerCase().includes(lower)).slice(0,6);openModal(`<span class="eyebrow">SEARCH</span><h2>Results for “${esc(q)}”</h2><h3>Study</h3>${study.map(x=>`<button class="compact-row" onclick="closeModal();enter('study');setTimeout(()=>openModule('${esc(x.id)}'),100)"><b>${esc(x.title)}</b><small>${esc(x.description)}</small></button>`).join('')||'<p class="muted">No study match.</p>'}<h3>N&MC Practice Questions</h3>${questions.map(x=>`<button class="compact-row" onclick="jumpToQuestion('${esc(x.id)}')"><b>${esc(x.question)}</b><small>${esc(x.domain)} · ${esc(x.difficulty||'Practice')}</small></button>`).join('')||'<p class="muted">No question match.</p>'}<h3>Jobs</h3>${jobs.map(x=>`<button class="compact-row" onclick="closeModal();openJob('${esc(x.id)}')"><b>${esc(x.title)}</b><small>${esc(x.country)}</small></button>`).join('')||'<p class="muted">No job match.</p>'}<h3>News</h3>${news.map(x=>`<button class="compact-row" onclick="openNews('${esc(x.id)}')"><b>${esc(x.title)}</b><small>${esc(x.date)}</small></button>`).join('')||'<p class="muted">No news match.</p>'}`)}
updateNotifyCount();
boot();
